unint32 i;
unint32 sat_mask = 0U;
unint32 slew_mask = 0U;
unint32 unavailable_mask = 0U;
int fault = 0;
adcs_vec3_t norm_axes[3];
double desired[3];
double limited[3];
double req_torque[3];
adcs_vec3_t achieved = {0.0, 0.0, 0.0};
adcs_vec3_t residual;
double resid_norm;

/* --- Disable: reset NORMAL and zero previous commands --- */
if (!wa_input.enable) {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

/* --- Validation --- */
if (wa_input.requested_torque_nm == NULL || wa_input.axes == NULL) {
    fault = 1;
}
if (wa_input.axis_count != 3U) {
    fault = 1;
}
if (!fault && !adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
    fault = 1;
}
if (!fault && (wa_input.available_mask & ~0x7U) != 0U) {
    fault = 1;
}
if (!fault) {
    for (i = 0U; i < 3U; i++) {
        if (!adcs_is_finite_vec3(&wa_input.axes[i])) {
            fault = 1;
            break;
        }
        if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &norm_axes[i]) != ADCS_OK) {
            fault = 1;
            break;
        }
    }
}
if (!fault) {
    double d01 = adcs_vec3_dot(&norm_axes[0], &norm_axes[1]);
    double d02 = adcs_vec3_dot(&norm_axes[0], &norm_axes[2]);
    double d12 = adcs_vec3_dot(&norm_axes[1], &norm_axes[2]);
    if (fabs(d01) > ADCS_EPS_COLLINEAR || fabs(d02) > ADCS_EPS_COLLINEAR ||
        fabs(d12) > ADCS_EPS_COLLINEAR) {
        fault = 1;
    }
}
if (!fault) {
    unint32 m = wa_input.available_mask & 0x7U;
    unint32 cnt = 0U;
    for (i = 0U; i < 3U; i++) {
        if (m & (1U << i)) cnt++;
    }
    if (cnt < 2U) fault = 1;
}
if (!fault) {
    for (i = 0U; i < 3U; i++) {
        if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0) {
            fault = 1;
            break;
        }
        if (!isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) ||
            wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0) {
            fault = 1;
            break;
        }
    }
}
if (!fault) {
    if (wa_config.release_cycles < 1U || wa_config.release_cycles > 20U ||
        wa_config.restore_cycles < 1U || wa_config.restore_cycles > 20U) {
        fault = 1;
    }
}

if (fault) {
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0x7U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    wa_state.mode = WA_FAULT;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    return;
}

/* --- Compute per-wheel desired torque, availability --- */
req_torque[0] = wa_input.requested_torque_nm->x;
req_torque[1] = wa_input.requested_torque_nm->y;
req_torque[2] = wa_input.requested_torque_nm->z;

for (i = 0U; i < 3U; i++) {
    if (!(wa_input.available_mask & (1U << i))) {
        unavailable_mask |= (1U << i);
        wa_output.wheel_torque_nm[i] = 0.0;
        desired[i] = 0.0;
    } else {
        desired[i] = -adcs_vec3_dot(&norm_axes[i], wa_input.requested_torque_nm);
    }
}

for (i = 0U; i < 3U; i++) {
    double lmin, lmax, d;
    if (!(wa_input.available_mask & (1U << i))) {
        continue;
    }
    lmin = -wa_config.wheel_limit_nm[i];
    lmax = wa_config.wheel_limit_nm[i];
    if (desired[i] > lmax) {
        limited[i] = lmax;
        sat_mask |= (1U << i);
    } else if (desired[i] < lmin) {
        limited[i] = lmin;
        sat_mask |= (1U << i);
    } else {
        limited[i] = desired[i];
    }
    d = limited[i] - wa_state.previous_wheel_torque_nm[i];
    if (d > wa_config.max_wheel_slew_nm_per_cycle[i]) {
        limited[i] = wa_state.previous_wheel_torque_nm[i] + wa_config.max_wheel_slew_nm_per_cycle[i];
        slew_mask |= (1U << i);
    } else if (d < -wa_config.max_wheel_slew_nm_per_cycle[i]) {
        limited[i] = wa_state.previous_wheel_torque_nm[i] - wa_config.max_wheel_slew_nm_per_cycle[i];
        slew_mask |= (1U << i);
    }
    wa_output.wheel_torque_nm[i] = limited[i];
}

/* --- Reconstruct achieved torque, residual --- */
achieved = (adcs_vec3_t){0.0, 0.0, 0.0};
for (i = 0U; i < 3U; i++) {
    if (wa_input.available_mask & (1U << i)) {
        achieved.x += wa_output.wheel_torque_nm[i] * norm_axes[i].x;
        achieved.y += wa_output.wheel_torque_nm[i] * norm_axes[i].y;
        achieved.z += wa_output.wheel_torque_nm[i] * norm_axes[i].z;
    }
}
residual.x = req_torque[0] - achieved.x;
residual.y = req_torque[1] - achieved.y;
residual.z = req_torque[2] - achieved.z;
resid_norm = sqrt(residual.x * residual.x + residual.y * residual.y + residual.z * residual.z);

wa_output.saturation_mask = sat_mask;
wa_output.slew_mask = slew_mask;
wa_output.unavailable_mask = unavailable_mask;
wa_output.achieved_torque_nm = achieved;
wa_output.residual_torque_nm = residual;
wa_output.residual_norm_nm = resid_norm;

/* --- State machine: limit events take precedence over health recovery --- */
if ((sat_mask != 0U) || (slew_mask != 0U)) {
    wa_output.mode = WA_LIMITED;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
} else if (unavailable_mask != 0U) {
    wa_output.mode = WA_DEGRADED;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
} else {
    if (wa_state.mode == WA_LIMITED) {
        unint32 cc = wa_state.clean_count + 1U;
        if (cc >= wa_config.release_cycles) {
            wa_output.mode = WA_RECOVERING;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
        } else {
            wa_output.mode = WA_LIMITED;
            wa_output.clean_count = cc;
            wa_output.restore_count = 0U;
        }
    } else if (wa_state.mode == WA_DEGRADED) {
        wa_output.mode = WA_RECOVERING;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
    } else if (wa_state.mode == WA_RECOVERING) {
        unint32 rc = wa_state.restore_count + 1U;
        if (rc >= wa_config.restore_cycles) {
            wa_output.mode = WA_NORMAL;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
        } else {
            wa_output.mode = WA_RECOVERING;
            wa_output.clean_count = 0U;
            wa_output.restore_count = rc;
        }
    } else {
        wa_output.mode = WA_NORMAL;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
    }
}

/* --- Persist state --- */
wa_state.mode = wa_output.mode;
wa_state.clean_count = wa_output.clean_count;
wa_state.restore_count = wa_output.restore_count;
for (i = 0U; i < 3U; i++) {
    wa_state.previous_wheel_torque_nm[i] = wa_output.wheel_torque_nm[i];
}

