adcs_vec3_t residual;
int valid = 1;
int limit_event = 0;

if (!wa_input.enable) {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 7U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

if (wa_state.mode == WA_FAULT) {
    wa_output.mode = WA_FAULT;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 7U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

if (wa_input.requested_torque_nm == NULL || wa_input.axes == NULL ||
    wa_input.axis_count != 3U) {
    valid = 0;
}
if (valid && !adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
    valid = 0;
}
if (valid) {
    for (i = 0; i < 3; i++) {
        if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
            !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) ||
            wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0) {
            valid = 0;
        }
    }
    if (wa_config.release_cycles < 1U || wa_config.release_cycles > 20U ||
        wa_config.restore_cycles < 1U || wa_config.restore_cycles > 20U) {
        valid = 0;
    }
    if ((wa_input.available_mask & ~7U) != 0U) {
        valid = 0;
    }
}
if (valid) {
    for (i = 0; i < 3; i++) {
        if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &norm_axis[i]) != ADCS_OK) {
            valid = 0;
        }
    }
}
if (valid) {
    for (i = 0; i < 3 && valid; i++) {
        for (j = i + 1; j < 3; j++) {
            double d = adcs_vec3_dot(&norm_axis[i], &norm_axis[j]);
            if (fabs(d) > ADCS_EPS_COLLINEAR) {
                valid = 0;
            }
        }
    }
}

if (!valid) {
    wa_state.mode = WA_FAULT;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 7U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

avail_mask_local = wa_input.available_mask & 7U;
unavail_mask_local = (~avail_mask_local) & 7U;
available_count = 0;
for (i = 0; i < 3; i++) {
    if ((avail_mask_local & (1U << i)) != 0U) {
        available_count++;
    }
}

req = *wa_input.requested_torque_nm;
wa_output.saturation_mask = 0U;
wa_output.slew_mask = 0U;
wa_output.unavailable_mask = unavail_mask_local;

for (i = 0; i < 3; i++) {
    if ((avail_mask_local & (1U << i)) == 0U) {
        tau[i] = 0.0;
        continue;
    }
    axis[i] = norm_axis[i];
    tau[i] = adcs_vec3_dot(&axis[i], &req);
    if (fabs(tau[i]) > wa_config.wheel_limit_nm[i]) {
        tau[i] = copysign(wa_config.wheel_limit_nm[i], tau[i]);
        wa_output.saturation_mask |= (uint32_t)(1U << i);
        limit_event = 1;
    }
    {
        double prev = wa_state.previous_wheel_torque_nm[i];
        double delta = tau[i] - prev;
        double slew = wa_config.max_wheel_slew_nm_per_cycle[i];
        if (delta > slew) {
            tau[i] = prev + slew;
            wa_output.slew_mask |= (uint32_t)(1U << i);
            limit_event = 1;
        } else if (delta < -slew) {
            tau[i] = prev - slew;
            wa_output.slew_mask |= (uint32_t)(1U << i);
            limit_event = 1;
        } else {
            /* within slew limit: hold commanded value */
        }
    }
}

achieved = (adcs_vec3_t){0.0, 0.0, 0.0};
for (i = 0; i < 3; i++) {
    if ((avail_mask_local & (1U << i)) != 0U) {
        adcs_vec3_t term = adcs_vec3_scale(&axis[i], tau[i]);
        achieved = adcs_vec3_add(&achieved, &term);
    }
}

residual = adcs_vec3_sub(&req, &achieved);

if (available_count < 2) {
    if (limit_event) {
        wa_state.mode = WA_LIMITED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else {
        wa_state.mode = WA_DEGRADED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    }
} else if (limit_event) {
    wa_state.mode = WA_LIMITED;
    wa_state.clean_count = 0U;
} else if (wa_state.mode == WA_FAULT) {
    wa_state.mode = WA_FAULT;
} else if (wa_state.mode == WA_LIMITED) {
    wa_state.clean_count++;
    if (wa_state.clean_count >= wa_config.release_cycles) {
        if (available_count == 3) {
            wa_state.mode = WA_RECOVERING;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else {
            wa_state.mode = WA_DEGRADED;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        }
    }
} else if (wa_state.mode == WA_DEGRADED) {
    if (available_count == 3) {
        wa_state.mode = WA_RECOVERING;
        wa_state.restore_count = 0U;
        wa_state.clean_count = 0U;
    }
} else if (wa_state.mode == WA_RECOVERING) {
    if (available_count < 3) {
        wa_state.mode = WA_DEGRADED;
        wa_state.restore_count = 0U;
        wa_state.clean_count = 0U;
    } else {
        wa_state.restore_count++;
        if (wa_state.restore_count >= wa_config.restore_cycles) {
            wa_state.mode = WA_NORMAL;
            wa_state.restore_count = 0U;
            wa_state.clean_count = 0U;
        }
    }
} else {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
}

for (i = 0; i < 3; i++) {
    wa_output.wheel_torque_nm[i] = tau[i];
    wa_state.previous_wheel_torque_nm[i] = tau[i];
}
wa_output.achieved_torque_nm = achieved;
wa_output.residual_torque_nm = residual;
wa_output.residual_norm_nm = adcs_vec3_norm(&residual);
wa_output.mode = wa_state.mode;
wa_output.clean_count = wa_state.clean_count;
wa_output.restore_count = wa_state.restore_count;

