        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 0U;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm = (adcs_vec3_t){0,0,0};
        wa_output.residual_torque_nm = (adcs_vec3_t){0,0,0};
        wa_output.residual_norm_nm = 0.0;
        return;
    }

    if (wa_input.requested_torque_nm == NULL || wa_input.axes == NULL ||
        wa_input.axis_count != 3U ||
        (wa_input.available_mask & ~0x7U) != 0U ||
        !adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
        valid = 0;
    }
    if (valid) {
        for (i = 0; i < 3U; i++) {
            if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
                !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) ||
                wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0) {
                valid = 0;
                break;
            }
        }
    }
    if (valid) {
        if (wa_config.release_cycles < 1U || wa_config.release_cycles > 20U ||
            wa_config.restore_cycles < 1U || wa_config.restore_cycles > 20U) {
            valid = 0;
        }
    }
    if (valid) {
        for (i = 0; i < 3U; i++) {
            if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes_n[i]) != ADCS_OK) {
                valid = 0;
                break;
            }
        }
    }
    if (valid) {
        if (fabs(adcs_vec3_dot(&axes_n[0], &axes_n[1])) > ADCS_EPS_COLLINEAR ||
            fabs(adcs_vec3_dot(&axes_n[1], &axes_n[2])) > ADCS_EPS_COLLINEAR ||
            fabs(adcs_vec3_dot(&axes_n[0], &axes_n[2])) > ADCS_EPS_COLLINEAR) {
            valid = 0;
        }
    }
    if (!valid) {
        wa_state.mode = WA_FAULT;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        wa_state.previous_wheel_torque_nm[0] = 0.0;
        wa_state.previous_wheel_torque_nm[1] = 0.0;
        wa_state.previous_wheel_torque_nm[2] = 0.0;
        wa_output.mode = WA_FAULT;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = (~wa_input.available_mask) & 0x7U;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm = (adcs_vec3_t){0,0,0};
        wa_output.residual_torque_nm = (wa_input.requested_torque_nm != NULL) ?
            *wa_input.requested_torque_nm : (adcs_vec3_t){0,0,0};
        wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);
        return;
    }

    avail = wa_input.available_mask & 0x7U;
    missing = (~avail) & 0x7U;

    {
        unint32 cnt = 0U;
        for (i = 0; i < 3U; i++) if ((avail >> i) & 1U) cnt++;
        if (cnt < 2U) {
            wa_state.mode = WA_FAULT;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
            wa_state.previous_wheel_torque_nm[0] = 0.0;
            wa_state.previous_wheel_torque_nm[1] = 0.0;
            wa_state.previous_wheel_torque_nm[2] = 0.0;
            wa_output.mode = WA_FAULT;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
            wa_output.saturation_mask = 0U;
            wa_output.slew_mask = 0U;
            wa_output.unavailable_mask = missing;
            wa_output.wheel_torque_nm[0] = 0.0;
            wa_output.wheel_torque_nm[1] = 0.0;
            wa_output.wheel_torque_nm[2] = 0.0;
            wa_output.achieved_torque_nm = (adcs_vec3_t){0,0,0};
            wa_output.residual_torque_nm = *wa_input.requested_torque_nm;
            wa_output.residual_norm_nm = adcs_vec3_norm(wa_input.requested_torque_nm);
            return;
        }
    }

    wa_output.unavailable_mask = missing;
    if (missing != 0U) health_degraded = 1;

    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;

    for (i = 0; i < 3U; i++) {
        if ((avail >> i) & 1U) {
            double desired, sat, slewed, prev, limit;

            limit = wa_config.wheel_limit_nm[i];
            desired = adcs_vec3_dot(&axes_n[i], wa_input.requested_torque_nm);
            sat = desired;
            if (sat > limit) {
                sat = limit;
                wa_output.saturation_mask |= (1U << i);
                limit_event = 1;
            } else if (sat < -limit) {
                sat = -limit;
                wa_output.saturation_mask |= (1U << i);
                limit_event = 1;
            }
            prev = wa_state.previous_wheel_torque_nm[i];
            slewed = sat;
            if (sat - prev > wa_config.max_wheel_slew_nm_per_cycle[i]) {
                slewed = prev + wa_config.max_wheel_slew_nm_per_cycle[i];
                wa_output.slew_mask |= (1U << i);
                limit_event = 1;
            } else if (prev - sat > wa_config.max_wheel_slew_nm_per_cycle[i]) {
                slewed = prev - wa_config.max_wheel_slew_nm_per_cycle[i];
                wa_output.slew_mask |= (1U << i);
                limit_event = 1;
            }
            wa_output.wheel_torque_nm[i] = slewed;
            wa_state.previous_wheel_torque_nm[i] = slewed;
        } else {
            wa_output.wheel_torque_nm[i] = 0.0;
            wa_state.previous_wheel_torque_nm[i] = 0.0;
        }
    }

    {
        adcs_vec3_t achieved = {0,0,0}, term;
        for (i = 0; i < 3U; i++) {
            term = adcs_vec3_scale(&axes_n[i], wa_output.wheel_torque_nm[i]);
            achieved = adcs_vec3_add(&achieved, &term);
        }
        wa_output.achieved_torque_nm = achieved;
        wa_output.residual_torque_nm = adcs_vec3_sub(wa_input.requested_torque_nm, &achieved);
        wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);
    }

    if (limit_event) {
        wa_state.mode = WA_LIMITED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else if (health_degraded) {
        wa_state.mode = WA_DEGRADED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else {
        switch (wa_state.mode) {
        case WA_LIMITED:
            if (wa_state.clean_count + 1U >= wa_config.release_cycles) {
                wa_state.clean_count = 0U;
                if (wa_config.restore_cycles <= 1U) {
                    wa_state.restore_count = 0U;
                    wa_state.mode = WA_NORMAL;
                } else {
                    wa_state.restore_count = 1U;
                    wa_state.mode = WA_RECOVERING;
                }
            } else {
                wa_state.clean_count++;
                wa_state.mode = WA_LIMITED;
            }
            break;
        case WA_DEGRADED:
            if (wa_config.restore_cycles <= 1U) {
                wa_state.restore_count = 0U;
                wa_state.mode = WA_NORMAL;
            } else {
                wa_state.restore_count = 1U;
                wa_state.mode = WA_RECOVERING;
            }
            wa_state.clean_count = 0U;
            break;
        case WA_RECOVERING:
            if (wa_state.restore_count + 1U >= wa_config.restore_cycles) {
                wa_state.restore_count = 0U;
                wa_state.mode = WA_NORMAL;
            } else {
                wa_state.restore_count++;
                wa_state.mode = WA_RECOVERING;
            }
            break;
        default:
            wa_state.mode = WA_NORMAL;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
            break;
        }
    }

    wa_output.mode = wa_state.mode;
    wa_output.clean_count = wa_state.clean_count;
    wa_output.restore_count = wa_state.restore_count;
}

