    wa_output.slew_mask = 0U;

    for (i = 0; i < 3U; i++) {
        if ((avail >> i) & 1U) {
            double desired, sat, slewed, prev, limit;

            limit = wa_config.wheel_limit_nm[i];
            desired = adcs_vec3_dot(&axes_n[i], wa_input.requested_torque_nm);
            sat = desired;
            if (sat > limit) {
                sat = limit;
                wa_output.saturation_mask |= (1U << i);
                limit_event = 1;
            } else if (sat < -limit) {
                sat = -limit;
                wa_output.saturation_mask |= (1U << i);
                limit_event = 1;
            }
            prev = wa_state.previous_wheel_torque_nm[i];
            slewed = sat;
            if (sat - prev > wa_config.max_wheel_slew_nm_per_cycle[i]) {
                slewed = prev + wa_config.max_wheel_slew_nm_per_cycle[i];
                wa_output.slew_mask |= (1U << i);
                limit_event = 1;
            } else if (prev - sat > wa_config.max_wheel_slew_nm_per_cycle[i]) {
                slewed = prev - wa_config.max_wheel_slew_nm_per_cycle[i];
                wa_output.slew_mask |= (1U << i);
                limit_event = 1;
            }
            wa_output.wheel_torque_nm[i] = slewed;
            wa_state.previous_wheel_torque_nm[i] = slewed;
        } else {
            wa_output.wheel_torque_nm[i] = 0.0;
            wa_state.previous_wheel_torque_nm[i] = 0.0;
        }
    }

    {
        adcs_vec3_t achieved = {0,0,0}, term;
        for (i = 0; i < 3U; i++) {
            term = adcs_vec3_scale(&axes_n[i], wa_output.wheel_torque_nm[i]);
            achieved = adcs_vec3_add(&achieved, &term);
